    if 'Small Note' not in [x.name for x in d.styles]:
        x=d.styles.add_style('Small Note',WD_STYLE_TYPE.PARAGRAPH); x.font.name='Arial'; x.font.size=Pt(8); x.font.italic=True
    h=s.header.paragraphs[0]; h.text='PRIVILEGED & CONFIDENTIAL — ATTORNEY WORK PRODUCT'; h.alignment=WD_ALIGN_PARAGRAPH.CENTER; h.runs[0].font.size=Pt(8); h.runs[0].font.bold=True
    f=s.footer.paragraphs[0]; f.text='Polaris / Trident — TSA Review  |  '; f.runs[0].font.size=Pt(8); page_no(f)
def title(d,t,sub):
    p=d.add_paragraph(); p.alignment=WD_ALIGN_PARAGRAPH.CENTER; r=p.add_run(t); r.bold=True; r.font.size=Pt(20); r.font.color.rgb=DARK
    p=d.add_paragraph(); p.alignment=WD_ALIGN_PARAGRAPH.CENTER; r=p.add_run(sub); r.italic=True; r.font.size=Pt(11)
    for x in ['Prepared for: Victoria S. Andersen, Whitfield & Crane LLP','Client: Polaris Industrial Holdings, Inc. (Seller / Service Provider)','Draft reviewed: Trident first draft dated April 28, 2025','Review benchmark: Polaris TSA Playbook (Jan. 15, 2025) and APA §7.12 / Exhibit H']:
        p=d.add_paragraph(); p.alignment=WD_ALIGN_PARAGRAPH.CENTER; p.add_run(x).font.size=Pt(9)
    d.add_paragraph()
def box(d,label,text,fill=PALE_YELLOW):
    t=d.add_table(rows=1,cols=1); t.alignment=WD_TABLE_ALIGNMENT.CENTER; tbl_borders(t)
    c=t.cell(0,0); shade(c,fill); p=c.paragraphs[0]; r=p.add_run(label+' '); r.bold=True; p.add_run(text)
    d.add_paragraph()
def matrix(d,rows,heads):
    t=d.add_table(rows=1,cols=len(heads)); t.alignment=WD_TABLE_ALIGNMENT.CENTER; tbl_borders(t); repeat_header(t.rows[0])
    for i,h in enumerate(heads):
        c=t.rows[0].cells[i]; shade(c,DARK); p=c.paragraphs[0]; p.alignment=WD_ALIGN_PARAGRAPH.CENTER; r=p.add_run(h); r.bold=True; r.font.color.rgb=RGBColor(255,255,255); r.font.size=Pt(8)
    for row in rows:
        cs=t.add_row().cells
        for i,v in enumerate(row):
            cs[i].paragraphs[0].add_run(str(v)).font.size=Pt(8)
            if i==0: shade(cs[i],GRAY)
    return t
def block(d,cid,tier,head,draft,add,basis,risk,pos,comment,auth=''):
    p=d.add_paragraph(style='Heading 2'); r=p.add_run(f'{cid} — {head} [{tier}]'); r.bold=True; r.font.color.rgb=RED if tier=='CRITICAL' else (RGBColor(0xBF,0x7F,0) if tier=='SIGNIFICANT' else RGBColor(0x55,0x55,0x55))
    p=d.add_paragraph(); r=p.add_run('[DELETE — draft language] '); r.bold=True; r.font.color.rgb=RED; x=p.add_run(draft); x.font.color.rgb=RED; x.font.strike=True
    p=d.add_paragraph(); r=p.add_run('[ADD — Polaris proposal] '); r.bold=True; r.font.color.rgb=BLUE; x=p.add_run(add); x.font.color.rgb=BLUE; x.font.underline=True
    t=d.add_table(rows=3,cols=2); t.alignment=WD_TABLE_ALIGNMENT.CENTER; tbl_borders(t)
    for i,(l,v) in enumerate([('Basis / cross-reference',basis),('Risk if unchanged',risk),('Position',pos)]):
        shade(t.rows[i].cells[0],GRAY); t.rows[i].cells[0].paragraphs[0].add_run(l).bold=True; t.rows[i].cells[1].paragraphs[0].add_run(v)
    p=d.add_paragraph(); rr=p.add_run('MARGIN COMMENT '+cid); rr.bold=True; rr.font.color.rgb=RED; rr.font.size=Pt(8.5)
    try: d.add_comment([rr],comment+(' Authority: '+auth if auth else ''),author='Whitfield & Crane',initials='W&C')
    except Exception: pass
    t=d.add_table(rows=1,cols=1); tbl_borders(t); c=t.cell(0,0); shade(c,PALE_RED if tier=='CRITICAL' else PALE_YELLOW); p=c.paragraphs[0]; r=p.add_run('COMMENT: '); r.bold=True; r.font.color.rgb=RED; p.add_run(comment+(' Authority: '+auth if auth else ''))
    d.add_paragraph()

