s','Buyer-paid; 30-day notice; fee records only; 5% threshold.','Firm target'),('S-8','SIGNIFICANT','§12.1','No long-force-majeure exit','90-day termination trigger for affected services.','Firm target'),('S-9','SIGNIFICANT','§13','Buyer only $2M CGL','$5M CGL + umbrella, AI, waiver; limit Polaris burden.','$3M fallback'),('S-10','SIGNIFICANT','§15.1–15.2','Ohio / Cuyahoga litigation','PA law; AAA arbitration in Pittsburgh.','Firm target'),('S-11','SIGNIFICANT','new §15.12','No non-solicitation','12 months post-service; all service personnel.','Firm target; 6-month floor'),('M-1','MINOR','§15.3','Notice mismatch','Align with APA receipt / email rules.','Cleanup'),('M-2','MINOR','§11.2','Broad provider reps','Qualify to scope / standard / applicable law.','Negotiable'),('M-3','MINOR','B / §3.1','Industry-standard overlay','Use historical protocols; no external benchmark.','Firm principle'),('M-4','MINOR','Schedule H','Named personnel / FTE minimums','Illustrative list; seller discretion.','Cleanup'),]
