    p=d.add_paragraph(); rr=p.add_run('MARGIN COMMENT '+cid); rr.bold=True; rr.font.color.rgb=RED; rr.font.size=Pt(8.5)
    try: d.add_comment([rr],comment+(' Authority: '+auth if auth else ''),author='Whitfield & Crane',initials='W&C')
    except Exception: pass
    t=d.add_table(rows=1,cols=1); tbl_borders(t); c=t.cell(0,0); shade(c,PALE_RED if tier=='CRITICAL' else PALE_YELLOW); p=c.paragraphs[0]; r=p.add_run('COMMENT: '); r.bold=True; r.font.color.rgb=RED; p.add_run(comment+(' Authority: '+auth if auth else ''))
    d.add_paragraph()

